f"--{boundary}
"
                f"Content-Disposition: form-data; name="file"; filename="{file_path.name}"
"
                f"Content-Type: {content_type}

"

QWidget {
    background-color: #ffffff;
    color: #14204a;
    selection-background-color: #44b7ff;
    selection-color: #001170;
    font-family: "Segoe UI", "Arial";
    font-size: 10pt;
}
QMainWindow, QDialog, QSplashScreen {
    background-color: #ffffff;
}
QGroupBox {
    border: none;
    border-top: 1px solid #dce5f2;
    border-radius: 0;
    margin-top: 1.25em;
    padding: 12px 8px 8px 8px;
    background-color: #ffffff;
}
QGroupBox#wizardSection {
    /* The Wizard stacks several configuration sections inside one
       screen-safe window, so it uses a tighter vertical rhythm than the main
       GUI's scrollable settings panels. Same border, title and colours --
       only the padding differs, which is what keeps Map feedback on one
       screen at 1080p instead of scrolling. */
    margin-top: 1.05em;
    padding: 8px 8px 6px 8px;
}
QGroupBox::title {
    subcontrol-origin: margin;
    left: 0;
    padding: 0 8px 0 0;
    color: #001170;
    background-color: #ffffff;
    font-size: 10pt;
    font-weight: 600;
}
QLineEdit, QTextEdit, QPlainTextEdit, QSpinBox, QDoubleSpinBox, QComboBox {
    background-color: #ffffff;
    color: #14204a;
    border: none;
    border-bottom: 1px solid #cbd7ea;
    border-radius: 0;
    padding: 4px 6px;
    min-height: 22px;
    selection-background-color: #44b7ff;
}
QLineEdit:hover, QTextEdit:hover, QPlainTextEdit:hover,
QSpinBox:hover, QDoubleSpinBox:hover, QComboBox:hover {
    border-bottom-color: #8fb6da;
}
QLineEdit:focus, QTextEdit:focus, QPlainTextEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QComboBox:focus {
    border: none;
    border-bottom: 2px solid #2264b8;
}
QSpinBox, QDoubleSpinBox {
    padding-right: 29px;
}
QSpinBox::up-button, QDoubleSpinBox::up-button {
    subcontrol-origin: border;
    subcontrol-position: top right;
    width: 25px;
    background-color: #f2f4f9;
    border: none;
    border-left: 1px solid #cbd7ea;
    border-bottom: 1px solid #cbd7ea;
}
QSpinBox::down-button, QDoubleSpinBox::down-button {
    subcontrol-origin: border;
    subcontrol-position: bottom right;
    width: 25px;
    background-color: #f2f4f9;
    border: none;
    border-left: 1px solid #cbd7ea;
}
QSpinBox::up-button:hover, QSpinBox::down-button:hover,
QDoubleSpinBox::up-button:hover, QDoubleSpinBox::down-button:hover {
    background-color: #e2f4ff;
}
QSpinBox::up-button:pressed, QSpinBox::down-button:pressed,
QDoubleSpinBox::up-button:pressed, QDoubleSpinBox::down-button:pressed {
    background-color: #c8eaff;
}
QComboBox {
    padding-right: 29px;
}
QComboBox::drop-down {
    subcontrol-origin: border;
    subcontrol-position: top right;
    width: 25px;
    background-color: #f2f4f9;
    border: none;
    border-left: 1px solid #cbd7ea;
}
QComboBox::drop-down:hover {
    background-color: #e2f4ff;
}
QComboBox::drop-down:pressed, QComboBox::drop-down:on {
    background-color: #c8eaff;
}
QWidget#phaseStudioArrowOverlay {
    background-color: transparent;
    border: none;
}
QWidget#settingsPage QLineEdit,
QWidget#settingsPage QSpinBox,
QWidget#settingsPage QDoubleSpinBox,
QWidget#settingsPage QComboBox {
    min-height: 21px;
    padding-top: 3px;
    padding-bottom: 3px;
}
QWidget#settingsPage QLineEdit[metadataInvalid="true"] {
    border-bottom: 2px solid #001170;
    background-color: #e2f4ff;
}
QWidget#settingsPage QSpinBox,
QWidget#settingsPage QDoubleSpinBox {
    min-height: 22px;
    max-height: 22px;
    padding-top: 2px;
    padding-bottom: 3px;
    padding-right: 29px;
}
QWidget#settingsPage QComboBox {
    padding-right: 29px;
}
QWidget#settingsPage QPushButton {
    min-height: 21px;
    padding: 3px 10px;
}
QPushButton#pathBrowseButton {
    min-height: 21px;
    padding: 3px 0;
    color: #001170;
    background-color: #f2f4f9;
    border: none;
    border-left: 1px solid #cbd7ea;
    border-bottom: 1px solid #cbd7ea;
}
QPushButton#pathBrowseButton:hover {
    color: #2264b8;
    background-color: #e2f4ff;
    border-left-color: #cbd7ea;
    border-bottom-color: #8fb6da;
}
QPushButton#pathBrowseButton:pressed {
    color: #001170;
    background-color: #c8eaff;
}
QPushButton#pathBrowseButton:disabled {
    color: #8794ad;
    background-color: #e7ecf3;
    border-left-color: #cbd7ea;
    border-bottom-color: #cbd7ea;
}
QPushButton {
    background-color: #ffffff;
    color: #001170;
    border: 1px solid #2264b8;
    border-radius: 0;
    padding: 5px 12px;
    min-height: 24px;
    font-weight: 600;
}
QPushButton:hover {
    background-color: #44b7ff;
    border-color: #2264b8;
}
QPushButton:pressed {
    background-color: #2264b8;
    color: #ffffff;
}
QPushButton:disabled {
    color: #7183a6;
    background-color: #f5f7fa;
    border-color: #cbd7ea;
}
QLineEdit:disabled, QTextEdit:disabled, QPlainTextEdit:disabled,
QSpinBox:disabled, QDoubleSpinBox:disabled, QComboBox:disabled {
    /* A disabled control must still be READABLE: the Map feedback page shows
       real configured values ("1", "0.000") in controls that are disabled
       until their feature is switched on, and at the previous #8794ad they
       washed out against the light field (~2.9:1). This muted navy reaches
       ~4.9:1 on the same background while staying clearly lighter than the
       enabled #001170, so the control still reads as disabled. */
    color: #5a6b8c;
    background-color: #f1f4f8;
    border-bottom-color: #cbd7ea;
}
QLabel:disabled, QCheckBox:disabled {
    color: #5a6b8c;
}
QLineEdit[configurationLocked="true"]:disabled,
QTextEdit[configurationLocked="true"]:disabled,
QPlainTextEdit[configurationLocked="true"]:disabled,
QSpinBox[configurationLocked="true"]:disabled,
QDoubleSpinBox[configurationLocked="true"]:disabled,
QComboBox[configurationLocked="true"]:disabled {
    /* A locked-during-RUNNING value must stay comfortably readable -- this
       is the configuration actively being used, not a genuinely irrelevant
       field -- while remaining clearly lower-contrast than an enabled
       control. Medium-muted navy rather than the near-invisible gray a
       plain :disabled state would give it. */
    color: #3d4d73;
    background-color: #edf2f8;
    border-bottom-color: #aebdd2;
}
QLabel[configurationLocked="true"]:disabled,
QCheckBox[configurationLocked="true"]:disabled {
    color: #4f5f87;
}
QSpinBox:disabled::up-button, QSpinBox:disabled::down-button,
QDoubleSpinBox:disabled::up-button, QDoubleSpinBox:disabled::down-button,
QComboBox:disabled::drop-down {
    background-color: #e7ecf3;
    border-left-color: #cbd7ea;
}
QTabWidget::pane {
    border: none;
    border-radius: 0;
    background-color: #ffffff;
}
QTabBar::tab {
    background-color: #f2f4f9;
    color: #001170;
    border: none;
    border-bottom: 1px solid #cbd7ea;
    padding: 6px 12px;
    margin-right: 1px;
    border-top-left-radius: 0;
    border-top-right-radius: 0;
